def is_permutation(coeffs, p):
    s = set()
    for x in range(p):
        val = 0
        power = 1
        for c in coeffs:
            val = (val + c * power) % p
            power = (power * x) % p
        s.add(val)
    return len(s) == p

def check_a3_nonzero(p):
    found = []
    for a3 in range(1, p):
        for a1 in range(p):
            if is_permutation([0, a1, 0, a3], p):
                found.append((a3, a1))
    return found

print(f"a3_nonzero for p=61: {check_a3_nonzero(61)}")
print(f"a3_nonzero for p=11: {check_a3_nonzero(11)}")
